model Product {
  id: ID
  name: String
  price: Number
}

component ProductCard(product: Product, onAdd: Fn) {
  button `${product.name} - $${product.price.toFixed(2)}` primary -> onAdd()
}

component CartItem(product: Product, quantity: Number, onIncrease: Fn, onDecrease: Fn) {
  row align=center justify=between pad=2 {
    column {
      text product.name bold
      text `$${product.price.toFixed(2)}` muted small
    }
    row gap=2 align=center {
      button "-" -> onDecrease()
      text quantity bold
      button "+" primary -> onIncrease()
    }
    text `$${(product.price * quantity).toFixed(2)}` bold
  }
}

page Shop "/shop" {
  state products: Product[] = [
    { id: "1", name: "Laptop", price: 999.99 },
    { id: "2", name: "Mouse", price: 29.99 },
    { id: "3", name: "Teclado", price: 79.99 }
  ]

  state cart: { productId: String, quantity: Number }[] = []

  computed total = cart.reduce((sum, item) => {
    let product = products.find(p => p.id == item.productId)
    return sum + (product ? product.price * item.quantity : 0)
  }, 0)

  fn addToCart(productId) {
    let existing = cart.find(item => item.productId == productId)
    if existing {
      existing.quantity++
    } else {
      cart.push({ productId, quantity: 1 })
    }
  }

  fn increaseQuantity(productId) {
    let item = cart.find(i => i.productId == productId)
    if item {
      item.quantity++
    }
  }

  fn decreaseQuantity(productId) {
    let item = cart.find(i => i.productId == productId)
    if item {
      item.quantity--
      if item.quantity == 0 {
        cart = cart.filter(i => i.productId != productId)
      }
    }
  }

  column gap=6 pad=4 {
    row gap=6 {
      column gap=4 {
        title "Productos"
        for p in products {
          ProductCard product=p onAdd=(() => addToCart(p.id))
        }
      }

      card {
        column gap=4 {
          title "Carrito"
          if cart.length == 0 {
            text "El carrito está vacío" muted
          } else {
            column gap=2 {
              for item in cart {
                let product = products.find(p => p.id == item.productId)
                if product {
                  CartItem product=product quantity=item.quantity onIncrease=(() => increaseQuantity(item.productId)) onDecrease=(() => decreaseQuantity(item.productId))
                }
              }
            }
            divider
            row justify=between align=center pad=2 {
              text "Total:" bold large
              text `$${total.toFixed(2)}` bold large primary
            }
          }
        }
      }
    }
  }
}

