      text "Shopping Cart" bold
      if cart.length == 0 {
        text "Your cart is empty" muted
      } else {
        column gap=2 {
          for item in cart {
            CartItemRow item=item onIncrease=(() => increaseQuantity(item.product.id)) onDecrease=(() => decreaseQuantity(item.product.id))
          }
        }
        divider
        row gap=2 justify=end {
          text "Total:" bold
          text `$${total.toFixed(2)}` bold large primary
