page Shop "/" {
  state cart = []

  computed total = cart.reduce((sum, item) => (sum + item.product.price * item.quantity), 0)

  fn addToCart(product) {
    let existing = cart.find(item => (item.product.id == product.id))
    if existing {
      existing.quantity = existing.quantity + 1
    } else {
      cart.push({ product: product, quantity: 1 })
    }
  }

  fn increaseQuantity(productId) {
    let item = cart.find(i => (i.product.id == productId))
    if item {
      item.quantity = item.quantity + 1
    }
  }

  fn decreaseQuantity(productId) {
    let item = cart.find(i => (i.product.id == productId))
    if item {
      item.quantity = item.quantity - 1
      if item.quantity == 0 {
        cart = cart.filter(i => (i.product.id != productId))
      }
    }
  }

  column gap=6 pad=4 {
    title "Shop"

    column gap=4 {
      text "Available Products" bold
      row gap=4 wrap {
        ProductCard product=(({ id: "1", name: "Laptop", price: 999.99 })) onAdd=(() => addToCart(({ id: "1", name: "Laptop", price: 999.99 })))
        ProductCard product=(({ id: "2", name: "Mouse", price: 29.99 })) onAdd=(() => addToCart(({ id: "2", name: "Mouse", price: 29.99 })))
        ProductCard product=(({ id: "3", name: "Keyboard", price: 79.99 })) onAdd=(() => addToCart(({ id: "3", name: "Keyboard", price: 79.99 })))
      }
    }

    divider

    column gap=4 {
      text "Shopping Cart" bold
      if cart.length == 0 {
        text "Your cart is empty" muted
      } else {
        column gap=2 {
          for item in cart {
            CartItemRow item=item onIncrease=(() => increaseQuantity(item.product.id)) onDecrease=(() => decreaseQuantity(item.product.id))
          }
        }
