  computed startIndex = (page - 1) * itemsPerPage
  computed endIndex = startIndex + itemsPerPage
  computed items = Array.from({ length: 23 }, (_, i) => `Ítem ${i + 1}`)
  computed currentItems = items.slice(startIndex, endIndex)

  fn nextPage() {
    if page < totalPages {
      page++
    }
  }

  fn prevPage() {
    if page > 1 {
      page--
    }
  }

  column gap=4 pad=4 {
