component App {
  state currentPage = 0
  computed totalPages = 3
  computed itemsPerPage = 10
  computed startIndex = currentPage * itemsPerPage
  computed endIndex = startIndex + itemsPerPage
  computed items = Array.from({ length: 23 }, (_, i) => `Ítem ${i + 1}`)
  computed displayedItems = items.slice(startIndex, endIndex)
  computed canGoPrevious = currentPage > 0
  computed canGoNext = currentPage < totalPages - 1

  fn goToPrevious() {
    if canGoPrevious {
      currentPage--
    }
  }

  fn goToNext() {
    if canGoNext {
      currentPage++
    }
  }

  column gap=6 pad=4 {
    column gap=2 {
      for item in displayedItems {
        text item
      }
    }
    column gap=4 align=center {
      text `Página ${currentPage + 1} de ${totalPages}`
      row gap=2 {
        button "Anterior" disabled=!canGoPrevious -> goToPrevious()
        button "Siguiente" disabled=!canGoNext -> goToNext()
      }
    }
  }
}

