component Stopwatch {
  state time = 0
  state isRunning = false
  ref intervalId = null

  fn start {
    if !isRunning {
      isRunning = true
      intervalId = setInterval(() => {
        time++
      }, 100)
    }
  }

  fn pause {
    if isRunning {
      isRunning = false
      clearInterval(intervalId)
      intervalId = null
    }
  }

  fn restart {
    isRunning = false
    if intervalId != null {
      clearInterval(intervalId)
      intervalId = null
    }
    time = 0
  }

  column gap=4 align=center pad=8 {
    title "Cronómetro"
    text `Tiempo: ${time}`
    row gap=4 {
      button "Iniciar" primary -> start
      button "Pausar" -> pause
      button "Reiniciar" -> restart
    }
  }
}

