component Stopwatch {
  state time = 0
  state isRunning = false
  ref intervalId = null

  fn start {
    if isRunning { return }
    isRunning = true
    intervalId = setInterval(() => {
      time++
    }, 100)
  }

  fn pause {
    if !isRunning { return }
    isRunning = false
    clearInterval(intervalId)
    intervalId = null
  }

  fn restart {
    isRunning = false
    if intervalId != null {
      clearInterval(intervalId)
      intervalId = null
    }
    time = 0
  }

  column gap=4 align=center pad=6 {
    title "Cronómetro"
    text `Tiempo: ${time}` large
    row gap=2 {
      button "Iniciar" primary disabled=isRunning -> start()
      button "Pausar" disabled=!isRunning -> pause()
      button "Reiniciar" -> restart()
    }
  }
}

