component SignupForm {
  state step = 1
  state name = ""
  state plan = "Gratis"
  state newsletter = false
  state completed = false
  state nameError = ""

  fn nextStep {
    if step == 1 {
      if name == "" {
        nameError = "Nombre requerido"
        return
      }
      nameError = ""
      step = 2
    } else if step == 2 {
      step = 3
    }
  }

  fn prevStep {
    if step > 1 {
      step--
      nameError = ""
    }
  }

  fn confirm {
    completed = true
  }

  column gap=4 align=center pad=6 {
    if !completed {
      title `Paso ${step} de 3`
    }

    if completed {
      title `¡Listo, ${name}!`
    } else if step == 1 {
      column gap=2 {
        input name placeholder="Nombre"
        if nameError != "" {
          text nameError danger
        }
      }
      button "Siguiente" primary -> nextStep()
    } else if step == 2 {
      column gap=3 {
        select plan options=["Gratis", "Pro"]
        checkbox newsletter label="Recibir novedades"
      }
      row gap=2 {
        button "Atrás" -> prevStep()
        button "Siguiente" primary -> nextStep()
      }
    } else if step == 3 {
      column gap=3 align=center {
        text `${name} eligió ${plan}`
        if newsletter {
          text "Con novedades"
        }
      }
      row gap=2 {
        button "Atrás" -> prevStep()
        button "Confirmar" primary -> confirm()
      }
    }
  }
}

