model Task {
  id: ID
  title: String min=1 max=100
  done: Bool = false
}

api tasks: Task

component TaskItem(task: Task, onUpdate: Fn) {
  state isRenaming = false
  state newTitle = task.title

  fn markDone() {
    api.tasks.update(task.id, { done: true })
    onUpdate()
  }

  fn saveTitle() {
    if newTitle.trim() == "" { return }
    api.tasks.update(task.id, { title: newTitle.trim() })
    isRenaming = false
    onUpdate()
  }

  row align=center gap=2 {
    if isRenaming {
      input newTitle placeholder="Nuevo título" -> saveTitle()
      button "Guardar" primary -> saveTitle()
    } else {
      text `${task.title}${task.done ? " (hecha)" : ""}`
      if !task.done {
        button "Hecha" -> markDone()
      }
      button "Renombrar" -> isRenaming = true
    }
  }
}

page Tasks "/" {
  state taskTitle = ""
  state filter = "Todas"
  data allTasks = api.tasks.list()

  computed filteredTasks = filter == "Todas" ? allTasks : filter == "Pendientes" ? allTasks.filter(t => !t.done) : allTasks.filter(t => t.done)

  fn addTask() {
    if taskTitle.trim() == "" { return }
    api.tasks.create({ title: taskTitle.trim(), done: false })
    taskTitle = ""
    allTasks.reload()
  }

  column gap=4 align=center pad=4 {
    title "Gestor de Tareas"

    row gap=2 {
      input taskTitle placeholder="Tarea" -> addTask()
      button "Agregar" primary -> addTask()
    }

    select filter placeholder="Filtrar" options=["Todas", "Pendientes", "Hechas"]

    if filteredTasks.length == 0 {
      text "Sin tareas" muted
    } else {
      column gap=2 {
        for task in filteredTasks key task.id {
          TaskItem task=task onUpdate=(allTasks.reload())
        }
      }
    }
  }
}

