page Survey "/" {
  data votes = api.votes.list() live

  state dogsPercentage = 0
  state catsPercentage = 0
  state dogsCount = 0
  state catsCount = 0

  effect {
    let total = votes.length
    dogsCount = votes.filter(v => v.option == "Perros").length
    catsCount = votes.filter(v => v.option == "Gatos").length

    if total == 0 {
      dogsPercentage = 0
      catsPercentage = 0
    } else {
      dogsPercentage = Math.round((dogsCount / total) * 100)
      catsPercentage = Math.round((catsCount / total) * 100)
    }
  }

  fn reset() {
    for v in votes {
      api.votes.remove(v.id)
    }
  }

  column gap=6 pad=6 align=center {
    title "¿Perros o Gatos?"

    if votes.loading {
      spinner
    } else {
      column gap=4 {
        button `Votar Perros` primary -> api.votes.create({ option: "Perros" }) {
          text `Perros: ${dogsPercentage}% (${dogsCount} votos)`
        }

        button `Votar Gatos` primary -> api.votes.create({ option: "Gatos" }) {
          text `Gatos: ${catsPercentage}% (${catsCount} votos)`
        }
      }

      button "Reiniciar" danger -> reset()
    }
  }
}

