page Catalog "/catalog" {
  state search = ""
  state page = 0

  data total = api.products.count({ search })
  data items = api.products.list({
    search,
    sort: "number",
    limit: 5,
    offset: page * 5
  })

  fn loadExamples() {
    server.createExamples()
  }

  fn nextPage() {
    if (page + 1) * 5 < total {
      page++
    }
  }

  fn prevPage() {
    if page > 0 {
      page--
    }
  }

  fn onSearch(q) {
    search = q
    page = 0
  }

  column gap=4 pad=4 {
    title "Catálogo de Productos"

    row gap=2 {
      input search placeholder="Buscar" -> onSearch(search)
      button "Cargar ejemplos" -> loadExamples()
    }

    text `Total: ${total}`

    if items.loading {
      spinner
    } else {
      column gap=2 {
        for product in items {
          card {
            text product.name
          }
        }
      }
    }

    row gap=2 justify=center {
      button "Anterior" disabled=(page == 0) -> prevPage()
      text `Página ${page + 1}`
      button "Siguiente" disabled=((page + 1) * 5 >= total) -> nextPage()
    }
  }
}

