page Login "/login" {
  state email = ""
  state password = ""
  state error = ""
  data me = auth.me()

  fn handleSignup() {
    try {
      await auth.signup({ email, password })
    } catch (e) {
      error = e.message
    }
  }

  fn handleLogin() {
    try {
      await auth.login(email, password)
      error = ""
    } catch (e) {
      error = "Datos incorrectos"
    }
  }

  column gap=4 pad=4 align=center justify=center {
    if me {
      navigate("/")
    }
    card pad=6 {
      title "Notas privadas"
      input email placeholder="Email" type=email
      input password placeholder="Contraseña" type=password
      if error {
        text error danger
      }
      row gap=2 {
        button "Crear cuenta" -> handleSignup()
        button "Entrar" primary -> handleLogin()
      }
    }
  }
}

page Notes "/" requires login {
  state noteText = ""
  data me = auth.me()
  data notes = api.notes.list()

  fn addNote() {
    if noteText.trim() == "" { return }
    try {
      await api.notes.create({ text: noteText })
      noteText = ""
    } catch (e) {
      null
    }
  }

  fn deleteNote(id) {
    await api.notes.remove(id)
  }

  fn logout() {
    await auth.logout()
    navigate("/login")
  }

  column gap=4 pad=4 {
    row gap=2 align=center justify=between {
      text `Hola, ${me?.email}`
      button "Salir" -> logout()
    }
    row gap=2 {
      input noteText placeholder="Nota"
      button "Agregar" primary -> addNote()
    }
    if notes.loading {
      spinner
    }
    if notes.length == 0 {
      text "Sin notas" muted
    } else {
      for note in notes {
        row gap=2 align=center justify=between pad=2 {
          text note.text
          button icon="trash" small -> deleteNote(note.id)
        }
      }
    }
  }
}

page NotFound "*" {
  column gap=4 pad=4 align=center justify=center {
    title "Página no encontrada"
    link "Volver" to="/"
  }
}

