  fn deleteNote(id) {
    try {
      await api.notes.remove(id)
    } catch (e) {
      null
    }
  }

  column gap=4 {
    row gap=2 {
      input newNote placeholder="Nota" -> null
      button "Agregar" primary -> addNote()
    }
    if notes.loading {
      text "Cargando..." muted
    } else if notes.error {
      text notes.error danger
    } else if notes.length == 0 {
      text "Sin notas" muted
    } else {
      column gap=2 {
        for note in notes {
          card pad=3 {
